<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('commercial_manager');$user=current_user();$flashes=render_flashes();$currentPage='activity_log';$pageTitle='Activity Log';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);$rows=[];$exists=cm_table($conn,'commercial_manager_activity_log');if($exists){$s=$conn->prepare("SELECT * FROM commercial_manager_activity_log WHERE commercial_manager_id=? ORDER BY created_at DESC,id DESC LIMIT 200");$s->bind_param('i',$managerId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}require __DIR__.'/_layout_start.php';?>
<div class="cm-page-header"><div><span>Audit & Accountability</span><h2>Activity Log</h2><p>Commercial capability-pack generation and governance actions.</p></div></div><?php if(!$exists):?><div class="cm-alert cm-alert--warning">Import database/commercial_manager_portal.sql first.</div><?php endif;?><div class="cm-card"><div class="cm-activity"><?php foreach($rows as $x):?><article><i class="fas fa-fingerprint"></i><div><strong><?= e(cm_label($x['action'])) ?></strong><span><?= e(cm_datetime($x['created_at'])) ?></span><p><?= e($x['description']) ?></p></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="cm-empty"><i class="fas fa-clock-rotate-left"></i><strong>No activity recorded</strong></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>